"""Allowlisted shareable metadata; raw trajectories remain private operator evidence."""
import math
import re
from builder.context import sha256
from builder.trajectory import VERSION as SOURCE_VERSION

VERSION = 'public-trajectory-v1'


def integer(value):
    return value if type(value) is int and value >= 0 else None


def digest(value):
    return value if isinstance(value, str) and re.fullmatch(r'[0-9a-f]{64}', value) else None


def identity(value):
    return sha256(value.encode()) if isinstance(value, str) else None


def evidence(value):
    # References generated by the projector, never arbitrary host paths.
    return value if isinstance(value, str) and re.fullmatch(
        r'(?:request-\d+\.json|response-\d+\.sse|events\.jsonl:\d+|'
        r'(?:boundary|smoke)-tool/call-\d+(?:/(?:request|response)\.json)?)', value) else None


def choice(value, allowed):
    return value if value in allowed else None


def boolean(value):
    return value if type(value) is bool else None


def public_view(summary):
    """Project fixed fields only. This neither verifies evidence nor publishes it."""
    if summary.get('format') != SOURCE_VERSION:
        raise ValueError('Project a current trajectory; historical summaries are not relabelled')
    effort = summary['effort']
    counts = ('requests', 'tool_calls_observed', 'inspection_requests', 'inspections_completed',
              'smoke_requests', 'smoke_requests_observed', 'smoke_native_completions',
              'smoke_native_completions_observed', 'smoke_feedback_deliveries_observed',
              'token_usage_response_count')
    projected_effort = {k: integer(effort.get(k)) for k in counts}
    elapsed = effort.get('elapsed_seconds')
    projected_effort['elapsed_seconds'] = (elapsed if type(elapsed) in (float, int) and
        math.isfinite(elapsed) and elapsed >= 0 else None)
    usage = effort.get('token_usage')
    projected_effort['token_usage'] = ({k: integer(usage.get(k)) for k in
        ('input_tokens', 'output_tokens', 'total_tokens')} if isinstance(usage, dict) else None)
    projected_effort['token_usage_complete'] = boolean(effort.get('token_usage_complete'))
    coverage = summary['coverage']; smoke_coverage = coverage['smoke']
    view = dict(format=VERSION, source_format=SOURCE_VERSION,
        final_source_sha256=digest(summary.get('final_source_sha256')),
        effort=projected_effort,
        coverage={k: integer(coverage.get(k)) for k in ('retained_requests', 'retained_responses')},
        tool_actions=[], working_exports=[], boundary_calls=[], smoke_calls=[],
        interpretation='not_inferred', scientific_score_effect='none',
        evidence_status='descriptive_projection_not_verification')
    view['coverage'].update({k: boolean(coverage.get(k)) for k in
        ('request_inventory_complete', 'response_inventory_complete')})
    view['coverage']['smoke'] = {k: integer(smoke_coverage.get(k)) for k in
        ('retained_requests', 'declared_requests', 'runtime_requests')}
    view['coverage']['smoke'].update({k: boolean(smoke_coverage.get(k)) for k in
        ('request_inventory_complete', 'native_outcomes_complete')})
    for action in summary['tool_actions']:
        completion = action.get('command_completion') or {}
        exit_code = completion.get('item', {}).get('exit_code')
        view['tool_actions'].append(dict(turn=integer(action.get('turn')),
            call_id_sha256=identity(action.get('call_id')), tool_name_sha256=identity(action.get('tool')),
            evidence=evidence(action.get('evidence')), input_sha256=digest(action.get('input_sha256')),
            output_sha256=digest(action.get('output_sha256')),
            output_delivered_in=evidence(action.get('output_delivered_in')),
            literal_command_count=integer(action.get('literal_command_count')),
            command_completion_exit_code=exit_code if type(exit_code) is int else None,
            candidate_edit_requested=boolean(action.get('candidate_edit_requested'))))
    for item in summary['working_exports']:
        view['working_exports'].append(dict(turn=integer(item.get('turn')),
            call_id_sha256=identity(item.get('call_id')), evidence=evidence(item.get('evidence')),
            outcome=choice(item.get('outcome'), ('completed', 'command_failed', 'indeterminate')),
            execution_evidence=evidence(item.get('execution_evidence')),
            output_delivered_in=evidence(item.get('output_delivered_in'))))
    for item in summary['inspection_calls']:
        delivery = item.get('feedback_delivery') or {}
        view['boundary_calls'].append(dict(evidence=evidence(item.get('evidence')),
            completed=boolean(item.get('completed')), artifact_sha256=digest(item.get('artifact_sha256')),
            delivery_status=choice(delivery.get('status'),
                ('complete', 'incomplete_presentation', 'not_demonstrated')),
            delivered_in=evidence(delivery.get('delivered_in')),
            call_id_sha256=identity(delivery.get('call_id'))))
    for item in summary['smoke_calls']:
        delivery = item['feedback_delivery']
        view['smoke_calls'].append(dict(evidence=evidence(item.get('evidence')),
            call_number=integer(item.get('call_number')), request_turn=integer(item.get('request_turn')),
            status=choice(item.get('status'),
                ('completed', 'incomplete', 'indeterminate', 'not_started', 'missing_response')),
            native_outcome=choice(item.get('native_outcome'),
                ('completed', 'failed', 'interrupted', 'not_started', 'unknown')),
            working_xml_sha256=digest(item.get('working_xml_sha256')),
            smoke_xml_sha256=digest(item.get('smoke_xml_sha256')),
            delivery_status=choice(delivery.get('status'),
                ('complete', 'incomplete_presentation', 'not_demonstrated')),
            delivered_in=evidence(delivery.get('request')), delivered_turn=integer(delivery.get('turn')),
            call_id_sha256=identity(delivery.get('call_id')),
            subsequent_response_turns=[integer(r.get('turn')) for r in item['subsequent_responses']]))
    return view
